public class Book {
    // Fields for the book class
    private String title;
    private String author;
    private String ISBN;
    private int copiesAvailable;

    // Constructor to initialize book details
    public Book(String title, String author, String ISBN, int copiesAvailable) {
        this.title = title;
        this.author = author;
        this.ISBN = ISBN;
        this.copiesAvailable = copiesAvailable;
    }

    // Method to display book details
    public void displayBookInfo() {
        System.out.println("Title: " + title);
        System.out.println("Author: " + author);
        System.out.println("ISBN: " + ISBN);
        System.out.println("Copies Available: " + copiesAvailable);
    }

    // Method to add more copies of the book to the library
    public void addBookToLibrary(int newCopies) {
        if (newCopies > 0) {
            copiesAvailable += newCopies;
            System.out.println(newCopies + " copies have been added. Total copies now: " + copiesAvailable);
        } else {
            System.out.println("Invalid number of copies to add.");
        }
    }

    // Main method to test the functionality
    public static void main(String[] args) {
        // Create a new book object
        Book book1 = new Book("The Catcher in the Rye", "J.D. Salinger", "978-0-316-76948-0", 5);

        // Display book information
        book1.displayBookInfo();

        // Add more copies of the book
        book1.addBookToLibrary(3);

        // Display updated book information
        book1.displayBookInfo();
    }
}
```

