Method Overriding Discussion:
Method overriding occurs when a subclass provides a specific implementation for a method defined in its superclass with the same signature. It allows dynamic polymorphism (runtime polymorphism), where the method to execute is resolved at runtime based on the actual object being referenced.

```java
// Rentable interface
interface Rentable {
    void rent();
    double calculateRentalCost(int days);
}

// Abstract class Vehicle
abstract class Vehicle implements Rentable {
    protected String make;
    protected String model;
    protected int year;

    public Vehicle(String make, String model, int year) {
        this.make = make;
        this.model = model;
        this.year = year;
    }

    public void displayDetails() {
        System.out.println("Make: " + make);
        System.out.println("Model: " + model);
        System.out.println("Year: " + year);
    }
}

// Car subclass
class Car extends Vehicle {
    private double dailyRate;

    public Car(String make, String model, int year, double dailyRate) {
        super(make, model, year);
        this.dailyRate = dailyRate;
    }
```

    @Override

```java
public void rent() {
    System.out.println("Car rented: " + make + " " + model);
}
```

    @Override

```c
public double calculateRentalCost(int days) {
    return days * dailyRate;
}
```

    @Override

```java
public void displayDetails() {
        super.displayDetails();
        System.out.println("Daily Rental Rate: $" + dailyRate);
    }
}

// Truck subclass
class Truck extends Vehicle {
    private double dailyRate;
    private double cargoWeightLimit;

    public Truck(String make, String model, int year, double dailyRate, double cargoWeightLimit) {
        super(make, model, year);
        this.dailyRate = dailyRate;
        this.cargoWeightLimit = cargoWeightLimit;
    }
```

    @Override

```java
public void rent() {
    System.out.println("Truck rented: " + make + " " + model);
}
```

    @Override

```c
public double calculateRentalCost(int days) {
    return days * dailyRate;
}
```

    @Override

```java
public void displayDetails() {
        super.displayDetails();
        System.out.println("Daily Rental Rate: $" + dailyRate);
        System.out.println("Cargo Weight Limit: " + cargoWeightLimit + " tons");
    }
}

// Bike subclass
class Bike extends Vehicle {
    private double hourlyRate;

    public Bike(String make, String model, int year, double hourlyRate) {
        super(make, model, year);
        this.hourlyRate = hourlyRate;
    }
```

    @Override

```java
public void rent() {
    System.out.println("Bike rented: " + make + " " + model);
}
```

    @Override

```c
public double calculateRentalCost(int days) {
    return days * 24 * hourlyRate;
}
```

    @Override

```java
public void displayDetails() {
        super.displayDetails();
        System.out.println("Hourly Rental Rate: $" + hourlyRate);
    }
}

// Main class
public class Main {
    public static void main(String[] args) {
        Car car = new Car("Toyota", "Camry", 2020, 50.0);
        car.displayDetails();
        car.rent();
        System.out.println("Rental cost for 5 days: $" + car.calculateRentalCost(5));
        System.out.println("----------------------------");

        Truck truck = new Truck("Ford", "F-150", 2019, 100.0, 5.0);
        truck.displayDetails();
        truck.rent();
        System.out.println("Rental cost for 3 days: $" + truck.calculateRentalCost(3));
        System.out.println("----------------------------");

        Bike bike = new Bike("Yamaha", "YZF-R3", 2021, 2.5);
        bike.displayDetails();
        bike.rent();
        System.out.println("Rental cost for 2 days: $" + bike.calculateRentalCost(2));
    }
}
```

Abstraction Discussion:
Abstraction allows hiding implementation details while exposing only essential features. The abstract `Vehicle` class centralizes shared attributes (`make`, `model`, `year`) and common methods (`displayDetails`), avoiding duplication across sub-classes.

